return $input.all().map(item => {
  const data = item.json;

  // Erwartete Ports aus der Data Table
  const expected = (data.expected_ports || '')
    .split(',')
    .map(p => Number(p.trim()))
    .filter(p => p > 0);

  // Tatsächlich von Shodan erkannte Ports
  const observed = data.ports || [];

  // Vergleich
  const missing = expected.filter(p => !observed.includes(p));
  const unexpected = observed.filter(p => !expected.includes(p));

  return {
    json: {
      name: data.name,
      ip: data.ip,
      environment: data.environment,

      expected_ports: expected,
      observed_ports: observed,

      missing_ports: missing,
      unexpected_ports: unexpected,

      vulnerabilities: data.vulns || [],

      security_status:
        unexpected.length > 0 ? 'WARNING' :
        missing.length > 0 ? 'NOTICE' :
        'OK'
    }
  };
});

const results = [];

for (const item of $input.all()) {
  const data = item.json;

  for (const cve of data.vulnerabilities || []) {
    results.push({
      json: {
        name: data.name,
        ip: data.ip,
        environment: data.environment,
        cve: cve,
        test_mode: true
      }
    });
  }
}

return results;

return $input.all().map(item => {
  const d = item.json;

  const cvss = Number(d.cvss_v3 ?? d.cvss ?? 0);
  const epss = Number(d.epss ?? 0);
  const kev = d.kev === true;

  let risk = 'LOW';

  if (kev || cvss >= 9) {
    risk = 'CRITICAL';
  } else if (cvss >= 7) {
    risk = 'HIGH';
  } else if (cvss >= 4) {
    risk = 'MEDIUM';
  }

  return {
    json: {
      asset: d.name,
      ip: d.ip,
      environment: d.environment,
      cve: d.cve_id,
      description: d.summary,
      cvss,
      epss,
      kev,
      risk,
      ransomware: d.ransomware_campaign || null,
      test_mode: d.test_mode === true
    }
  };
});

const grouped = {};

for (const item of $input.all()) {
  const d = item.json;
  const key = d.ip;

  if (!grouped[key]) {
    grouped[key] = {
      name: d.asset,
      ip: d.ip,
      environment: d.environment,
      vulnerabilities: []
    };
  }

  grouped[key].vulnerabilities.push({
    cve: d.cve,
    cvss: d.cvss,
    epss: d.epss,
    kev: d.kev,
    risk: d.risk,
    description: d.description,
    ransomware: d.ransomware
  });
}

return Object.values(grouped).map(item => ({
  json: item
}));

return $input.all().map(item => {
  const d = item.json;

  const vulns = d.vulnerabilities || [];

  const critical = vulns.filter(v => v.risk === 'CRITICAL').length;
  const high = vulns.filter(v => v.risk === 'HIGH').length;
  const medium = vulns.filter(v => v.risk === 'MEDIUM').length;

  const unexpectedPorts = d.unexpected_ports || [];

  let risk = 'LOW';

  if (critical > 0) {
    risk = 'CRITICAL';
  } else if (high > 0 || unexpectedPorts.length > 0) {
    risk = 'HIGH';
  } else if (medium > 0 || (d.missing_ports || []).length > 0) {
    risk = 'MEDIUM';
  }

  return {
    json: {
      ...d,
      risk_summary: {
        overall: risk,
        critical_cves: critical,
        high_cves: high,
        medium_cves: medium,
        unexpected_ports: unexpectedPorts.length
      }
    }
  };
});

const error = $input.first().json;

const workflow = error.workflow || {};
const execution = error.execution || {};
const details = error.execution?.error || error.error || {};

const esc = value => String(value ?? 'Unbekannt')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

const workflowName = workflow.name || 'Unbekannter Workflow';
const workflowId = workflow.id || 'Unbekannt';
const executionId = execution.id || 'Unbekannt';
const errorMessage = details.message || 'Keine Fehlerbeschreibung verfügbar';
const errorNode = details.node?.name || 'Unbekannt';
const timestamp = new Date().toLocaleString('de-DE', {
  timeZone: 'Europe/Berlin'
});

const html = `
<!DOCTYPE html>
<html>
<head><meta charset="UTF-8"></head>
<body style="font-family:Arial,sans-serif;background:#f3f4f6;padding:20px;color:#1f2937">
<div style="max-width:700px;margin:auto;background:white;padding:25px">

<h1 style="color:#dc2626">IT Security – Workflow-Fehler</h1>

<p>Ein Workflow konnte nicht erfolgreich ausgeführt werden.</p>

<table width="100%" cellpadding="10" style="border-collapse:collapse">
<tr style="background:#f3f4f6">
<td><b>Workflow</b></td>
<td>${esc(workflowName)}</td>
</tr>
<tr>
<td><b>Workflow-ID</b></td>
<td>${esc(workflowId)}</td>
</tr>
<tr style="background:#f3f4f6">
<td><b>Execution-ID</b></td>
<td>${esc(executionId)}</td>
</tr>
<tr>
<td><b>Fehlerhafter Node</b></td>
<td>${esc(errorNode)}</td>
</tr>
<tr style="background:#f3f4f6">
<td><b>Zeitpunkt</b></td>
<td>${esc(timestamp)}</td>
</tr>
</table>

<h2 style="color:#dc2626">Fehlerbeschreibung</h2>

<div style="background:#fee2e2;padding:15px;border-left:4px solid #dc2626">
${esc(errorMessage)}
</div>

<p style="margin-top:25px;color:#64748b;font-size:12px">
Automatische Benachrichtigung durch n8n IT Security Monitoring.
</p>

</div>
</body>
</html>
`;

return [{
  json: {
    subject: `⚠️ n8n Fehler: ${workflowName}`,
    html,
    workflowName,
    executionId
  }
}];
